// Reads the 18 hidden prompt fields from the form submission and reshapes them
// into [{ level, items: [{ type, prompt }, ...] }] — one item per (level x type).
const formSubmissions = $("On form submission").all();

const levels = ["EASY", "MEDIUM", "HARD"];
const formats = ["MCQ", "VSA", "SA", "LA", "A&R", "CASE_STUDY"];

const output = levels.map(level => {
  const items = formats.map(format => {
    const key = `${level} ${format}`;
    const submission = formSubmissions.find(s => s && s.json && s.json[key]);
    return { type: format, prompt: submission ? submission.json[key] : null };
  });
  return { level, items };
});

return output.map(o => ({ json: o }));

// On each outer-loop iteration this expands the current level's 6 (type, prompt) pairs
// and attaches the matching Drive level-folder id.
const levelIndex = $runIndex;
const levelsNode = $('Generate 18 Question Prompts').all();
if (!levelsNode[levelIndex]) {
  // Signal end of outer loop.
  return [];
}
const { level, items } = levelsNode[levelIndex].json;

const foldersNode = $('Create Level Folder').all();
const folder = foldersNode[levelIndex];
if (!folder || !folder.json || !folder.json.id) return [];
const folderId = folder.json.id;

if (!Array.isArray(items) || items.length === 0) return [];

return items.map(it => ({
  json: {
    level,
    parentFolderId: folderId,
    questionType: it.type,
    prompt: it.prompt
  }
}));
